static_start=source.index("  document.body.insertAdjacentHTML('afterbegin'")
static_end=source.index("\n\n  function $(id)",static_start)
static_block=source[static_start:static_end]
def replace_long(s, mapping):
    for old,new in sorted(mapping.items(),key=lambda kv:len(kv[0]),reverse=True):s=s.replace(old,new)
    return s

def translate_static_js_string(match, lang):
    raw=match.group(0); quote=raw[0]; value=raw[1:-1]
    # protect tag syntax; translate visible text and explicitly user-facing aria-label values
    pieces=re.split(r'(<[^>]*>)',value)
    for i,piece in enumerate(pieces):
        if piece.startswith('<'):
            def aria(m): return m.group(1)+replace_long(m.group(2),common[lang])+m.group(3)
            piece=re.sub(r'(aria-label=[\"\'])(.*?)([\"\'])',aria,piece)
            pieces[i]=piece
        else: pieces[i]=replace_long(piece,common[lang])
    return quote+''.join(pieces)+quote

for lang in ('en','es'):
    def translate_token(m):
        token=m.group(0)
        if token.startswith('//') or token.startswith('/*'):
            return token
        return translate_static_js_string(m,lang)
    token_pattern=r"/\*[\s\S]*?\*/|//[^\n]*|'(?:\\.|[^'\\])*'|\"(?:\\.|[^\"\\])*\""
    out=re.sub(token_pattern,translate_token,source)
    # Exact whole-string replacements for dynamic UI text only; never replace substrings of code literals.
    unsafe_exact={'revisar'} # this word is also a panel ID; UI text is translated only inside markup.
    for old,new in common[lang].items():
        if len(old)>=3 and old not in unsafe_exact:
            out=out.replace("'"+old+"'", "'"+new+"'").replace('"'+old+'"','"'+new+'"')
    # Preserve persisted theme values/keys; localize only the displayed labels.
    theme={'en':"var THEMES=[['dark','dark'],['papel','paper'],['sepia','sepia']];",'es':"var THEMES=[['dark','oscuro'],['papel','papel'],['sepia','sepia']];"}[lang]
    out=re.sub(r"var THEMES=\[\[[^\n]+",theme,out,count=1)
    # Localize dynamic text fragments exactly, while preserving storage/schema/selector keys.
    extra={
      'en':{"'sem pressa — '":"'No rush — '","' esperando por você'":"' waiting for you'","'nada esperando por você agora'":"'Nothing waiting for you right now'","'feito'":"'done'","'pendente'":"'pending'","'ir até ela'":"'Go to lesson'","'Aula '+k":"'Lesson '+k","'Aula '+k+(":"'Lesson '+k+(","'Seção '+(i+1)":"'Section '+(i+1)","'marcar como lido'":"'mark as read'","'mostrar resposta'":"'Show answer'","'de novo'":"'again'","'bom'":"'good'","'fácil'":"'easy'","'tempo: '+l":"'Theme: '+l","'tema: '+l":"'Theme: '+l","'Zerar todo o progresso do curso?'":"'Reset all course progress?'","'Arquivo inválido.'":"'Invalid file.'","'schema inválido'":"'invalid schema'"},
      'es':{"'sem pressa — '":"'Sin prisa — '","' esperando por você'":"' pendientes'","'nada esperando por você agora'":"'No hay nada pendiente ahora'","'feito'":"'hecho'","'pendente'":"'pendiente'","'ir até ela'":"'Ir a la clase'","'Aula '+k":"'Clase '+k","'Aula '+k+(":"'Clase '+k+(","'Seção '+(i+1)":"'Sección '+(i+1)","'marcar como lido'":"'marcar como leída'","'mostrar resposta'":"'Mostrar respuesta'","'de novo'":"'otra vez'","'bom'":"'bien'","'fácil'":"'fácil'","'tema: '+l":"'Tema: '+l","'Zerar todo o progresso do curso?'":"'¿Borrar todo el progreso del curso?'","'Arquivo inválido.'":"'Archivo no válido.'","'schema inválido'":"'esquema no válido'"}}
    for old,new in extra[lang].items():out=out.replace(old,new)
    # Keep each locale's saved learning state separate while retaining the course slug.
    ck_line = 'var CK=((document.querySelector(\'meta[name="curso"]\')||{}).content||"v4:curso")+":%s";' % lang
    out=re.sub(r'var CK=.*?;',ck_line,out,count=1)
    # English uses localized stats fields in tempoStats result; leave its persisted/data contract intact.
    for track in range(1,6):
        rel=Path('curso')/lang/f'trilha-{track}'/('curso.js' if track==4 else 'assets/curso.js')
        dest=ROOT/rel
        dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(out)
    print(f'generated {lang} shared UI from PT for 5 tracks')
